#!/usr/bin/env node
/**
 * LeadPilot AI — One-shot installer (v2 — with Edge Function deploy scripts)
 * ==========================================================================
 * Run: node install-leadpilot.js
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ZIP_BASE64 = "";

const OUT_ZIP = path.join(process.cwd(), 'leadpilot-ai.zip');
const OUT_DIR = path.join(process.cwd(), 'leadpilot-ai');

console.log('🚀 LeadPilot AI installer starting...');
console.log('   Decoding embedded archive (' + Math.round(ZIP_BASE64.length * 3 / 4 / 1024) + ' KB)...');

fs.writeFileSync(OUT_ZIP, Buffer.from(ZIP_BASE64, 'base64'));
console.log('   ✓ Wrote ' + OUT_ZIP);

if (fs.existsSync(OUT_DIR)) {
  console.error('❌ ./leadpilot-ai/ already exists. Move or delete it and re-run.');
  process.exit(1);
}

function tryUnzip() {
  if (process.platform === 'win32') {
    try {
      execSync('powershell -NoProfile -Command "Expand-Archive -Path leadpilot-ai.zip -DestinationPath . -Force"', { stdio: 'inherit' });
      return true;
    } catch (_) {}
  }
  try { execSync('unzip -q leadpilot-ai.zip', { stdio: 'inherit' }); return true; } catch (_) {}
  try { execSync('tar -xf leadpilot-ai.zip', { stdio: 'inherit' }); return true; } catch (_) {}
  return false;
}

if (tryUnzip()) {
  console.log('   ✓ Extracted to ' + OUT_DIR);
  fs.unlinkSync(OUT_ZIP);
  console.log('   ✓ Cleaned up zip');
  console.log('');
  console.log('✅ Done! Next steps:');
  console.log('   cd leadpilot-ai');
  console.log('   npm install');
  console.log('   cp .env.example .env.local      # then fill in your Supabase keys');
  console.log('   npm run dev');
  console.log('');
  console.log('To deploy Edge Functions to Supabase:');
  console.log('   Windows:  powershell -ExecutionPolicy Bypass -File scripts\\deploy-functions.ps1');
  console.log('   Mac/Lin:  chmod +x scripts/deploy-functions.sh && ./scripts/deploy-functions.sh');
} else {
  console.log('');
  console.log('⚠  Could not auto-unzip. Zip is at: ' + OUT_ZIP);
  console.log('   Extract manually (right-click → Extract All).');
}
